"use client";

import {
  useEffect,
  useMemo,
  useRef,
  type CSSProperties,
  type KeyboardEvent,
  type PointerEvent,
} from "react";
import { cx } from "@/lib/cx";

export interface TimelineScrubberItem {
  id: string;
  /** When it happened: a Date, an ISO string or a timestamp. Items run oldest first. */
  date: Date | string | number;
  /** Read out with the date, for example a title. */
  label?: string;
}

export interface TimelineScrubberProps {
  items: TimelineScrubberItem[];
  /** Selected item index. Uncontrolled when omitted, starting at the newest item. */
  value?: number;
  defaultValue?: number;
  /** Called whenever the selection moves: click, drag, the focus ring and the keyboard. */
  onChange?: (index: number) => void;
  /**
   * The marker's position in items, fractional while it glides. Reported on
   * every frame of a move the scrubber started, so a list can scroll in step.
   */
  onPositionChange?: (position: number) => void;
  /** First and last item in view, fractional. Their ticks darken like a scrollbar thumb. */
  inView?: readonly [number, number];
  /** Ratchet clicks as ticks pass under the marker. */
  sound?: boolean;
  /** How long a press is held before the focus ring opens, in milliseconds. */
  holdDelay?: number;
  locale?: string;
  className?: string;
  "aria-label"?: string;
}

// Geometry, in CSS pixels. Ticks sit on a uniform grid; a month boundary takes a grid step.
const MID = 58;
const TICK = 3;
const REST = 8;
const MAX_GAP = 9;
const MIN_GAP = 7;
const EDGE = 24;
const PITCH = 40;
const FINE_OPACITY = [1, 0.78, 0.42, 0.3, 0.22];
const FINE_SCALE = [1.1, 1, 0.93, 0.88, 0.84];

const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));
const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
/** Frame-rate independent approach to a target with time constant `tau` (ms). */
const approach = (v: number, to: number, tau: number, dt: number) =>
  v + (to - v) * (1 - Math.exp(-dt / tau));
const gauss = (r: number) => Math.exp(-(r * r) / (2.2 * 2.2));
const under = (r: number) => Math.max(0, 1 - r) ** 1.5;
const smooth = (t: number) => t * t * (3 - 2 * t);
const smoother = (t: number) => t * t * t * (t * (t * 6 - 15) + 10);

/* ---------- ratchet clicks ---------- */

type Click = "line" | "month" | "travel" | "fine" | "close";
const VOICES: Record<Click, { pitch: number; decay: number; level: number }> = {
  line: { pitch: 1, decay: 1, level: 1 },
  month: { pitch: 0.88, decay: 1.2, level: 1.1 },
  travel: { pitch: 1.08, decay: 0.8, level: 0.5 },
  fine: { pitch: 1.5, decay: 0.7, level: 0.55 },
  close: { pitch: 1.2, decay: 0.85, level: 0.4 },
};

/** A short ratchet click: high-passed noise with two ringing partials, rendered once per voice. */
function renderClick(ctx: AudioContext, pitch: number, decay: number) {
  const rate = ctx.sampleRate;
  const n = Math.round(rate * 0.04 * Math.max(1, decay));
  const out = new Float32Array(n);
  const w = (2 * Math.PI * 4000 * pitch) / rate;
  const cos = Math.cos(w);
  const alpha = Math.sin(w) / Math.SQRT2;
  const [b0, b1, b2] = [(1 + cos) / 2, -(1 + cos), (1 + cos) / 2];
  const [a0, a1, a2] = [1 + alpha, -2 * cos, 1 - alpha];
  let [x1, x2, y1, y2, peak] = [0, 0, 0, 0, 0];
  for (let i = 0; i < n; i++) {
    const t = i / rate;
    const x = Math.random() * 2 - 1;
    const y = (b0 * x + b1 * x1 + b2 * x2 - a1 * y1 - a2 * y2) / a0;
    [x2, x1, y2, y1] = [x1, x, y1, y];
    let s = 1.5 * y * Math.exp(-t / (0.00025 * decay));
    s += 0.6 * Math.sin(2 * Math.PI * 5200 * pitch * t) * Math.exp(-t / (0.0008 * decay));
    s += 0.4 * Math.sin(2 * Math.PI * 7400 * pitch * t) * Math.exp(-t / (0.0005 * decay));
    out[i] = s * Math.min(1, t / 1e-4);
    peak = Math.max(peak, Math.abs(out[i]));
  }
  const fade = Math.round(rate * 0.005);
  for (let i = 0; i < fade; i++) out[n - 1 - i] *= i / fade;
  for (let i = 0; i < n; i++) out[i] /= peak || 1;
  const buffer = ctx.createBuffer(1, n, rate);
  buffer.getChannelData(0).set(out);
  return buffer;
}

/** One audio context for every scrubber on the page, started by the first press. */
const audio = {
  ctx: null as AudioContext | null,
  buffers: {} as Partial<Record<Click, AudioBuffer>>,
  free: 0,
  queued: 0,
  pending: null as { kind: Click; level: number } | null,
  timer: 0,
  armed: false,
  /** Browsers start audio only from a gesture; the first press or key anywhere on the page starts it. */
  arm() {
    if (this.armed || typeof window === "undefined") return;
    this.armed = true;
    const start = () => this.unlock();
    for (const type of ["pointerdown", "keydown", "touchend"])
      window.addEventListener(type, start, { capture: true, passive: true });
  },
  unlock() {
    const Ctx =
      window.AudioContext ??
      (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!Ctx) return;
    if (!this.ctx || this.ctx.state === "closed") {
      this.ctx = new Ctx();
      this.buffers = {};
    }
    if (this.ctx.state !== "running") void this.ctx.resume().catch(() => {});
  },
  /** `each` clicks queue 20ms apart so a fast pass still ticks once per mark; others keep 60ms apart. */
  play(kind: Click, level = 1, each = false) {
    const ctx = this.ctx;
    if (ctx?.state !== "running") return;
    const now = ctx.currentTime;
    let at = now;
    if (each) {
      at = Math.max(now, this.queued);
      if (at - now > 0.25) return;
      this.queued = at + 0.02;
    } else if (now < this.free) {
      this.pending = { kind, level };
      this.timer ||= window.setTimeout(
        () => {
          this.timer = 0;
          const next = this.pending;
          this.pending = null;
          if (next) this.play(next.kind, next.level);
        },
        (this.free - now) * 1000 + 1,
      );
      return;
    }
    if (!each) this.free = at + 0.06;
    const voice = VOICES[kind];
    const source = ctx.createBufferSource();
    source.buffer = this.buffers[kind] ??= renderClick(ctx, voice.pitch, voice.decay);
    source.playbackRate.value = 1 + (Math.random() - 0.5) * 0.04;
    const gain = ctx.createGain();
    gain.gain.value = 0.2 * voice.level * level;
    source.connect(gain).connect(ctx.destination);
    source.start(at);
  },
};

/* ---------- rolling date digits ---------- */

/** A slot whose text rolls up or down when it changes, like a drum counter. */
function createReel(host: HTMLElement) {
  const box = document.createElement("span");
  box.style.cssText =
    "position:relative;display:inline-block;vertical-align:top;height:1.3em;transition:width .52s cubic-bezier(.4,0,.2,1)";
  host.append(box);
  let current: HTMLSpanElement | null = null;
  let text: string | null = null;
  return (next: string, dir: number, still: boolean) => {
    if (next === text) return;
    const el = document.createElement("span");
    el.style.cssText = "position:absolute;left:0;top:0;white-space:pre";
    el.textContent = next;
    box.append(el);
    box.style.width = next ? `${el.offsetWidth}px` : "0px";
    const old = current;
    if (old && dir && !still) {
      const ease = "cubic-bezier(.4,0,.2,1)";
      old
        .animate(
          [
            { transform: "translateY(0)", opacity: 1, filter: "blur(0)" },
            { transform: `translateY(${-dir * 70}%)`, opacity: 0, filter: "blur(2px)" },
          ],
          {
            duration: 420,
            easing: ease,
            fill: "forwards",
          },
        )
        .finished.then(
          () => old.remove(),
          () => old.remove(),
        );
      el.animate(
        [
          { transform: `translateY(${dir * 70}%)`, opacity: 0, filter: "blur(2px)" },
          { transform: "translateY(0)", opacity: 1, filter: "blur(0)" },
        ],
        {
          duration: 420,
          easing: ease,
        },
      );
    } else old?.remove();
    current = el;
    text = next;
  };
}

/* ---------- layout ---------- */

interface Layout {
  start: number;
  gap: number;
  /** Tick centres, one per slot; several items share a slot when the bar is short. */
  slotX: number[];
  slotItems: number[][];
  sepX: number[];
  itemX: number[];
  itemSlot: number[];
}

function measure(width: number, monthOf: number[], months: number): Layout {
  const n = monthOf.length;
  const counts = Array.from({ length: months }, (_, m) => monthOf.filter((v) => v === m).length);
  const usable = Math.max(0, width - 2 * EDGE);
  const plan = (k: number) => {
    const slots = counts.map((c) => clamp(Math.round((c * k) / Math.max(1, n)), 1, Math.max(1, c)));
    const marks = slots.reduce((a, b) => a + b, 0) + months - 1;
    return { slots, marks, gap: usable / Math.max(1, marks - 1) };
  };
  let p = plan(n);
  for (let k = n - 1; p.gap < MIN_GAP && k >= months; k--) p = plan(k);
  const gap = Math.min(MAX_GAP, p.gap);
  const start = (width - gap * (p.marks - 1)) / 2;
  const out: Layout = {
    start,
    gap,
    slotX: [],
    slotItems: [],
    sepX: [],
    itemX: new Array(n),
    itemSlot: new Array(n),
  };
  let x = start;
  let item = 0;
  counts.forEach((count, m) => {
    if (m > 0) {
      out.sepX.push(x);
      x += gap;
    }
    const slots = p.slots[m];
    const first = out.slotX.length;
    for (let s = 0; s < slots; s++) {
      out.slotX.push(x + s * gap);
      out.slotItems.push([]);
    }
    for (let t = 0; t < count; t++, item++) {
      const slot = first + Math.min(slots - 1, Math.floor(((t + 0.5) * slots) / count));
      out.itemX[item] = x + (((t + 0.5) * slots) / count - 0.5) * gap;
      out.itemSlot[item] = slot;
      out.slotItems[slot].push(item);
    }
    x += slots * gap;
  });
  return out;
}

const toDate = (d: TimelineScrubberItem["date"]) => (d instanceof Date ? d : new Date(d));

/**
 * A timeline scrollbar. Long ticks mark months, short ticks mark dates; the
 * ticks swell and warm under the pointer, which snaps from mark to mark.
 * Click to jump, drag to scrub, hold to open a focus ring of day numbers,
 * and every mark that passes clicks like a ratchet.
 */
export function TimelineScrubber({
  items,
  value,
  defaultValue,
  onChange,
  onPositionChange,
  inView,
  sound = true,
  holdDelay = 500,
  locale = "en-US",
  className,
  "aria-label": ariaLabel = "Timeline",
}: TimelineScrubberProps) {
  const n = items.length;
  const root = useRef<HTMLDivElement>(null);
  const ticks = useRef<(HTMLElement | null)[]>([]);
  const seps = useRef<(HTMLElement | null)[]>([]);
  const fine = useRef<(HTMLElement | null)[]>([]);
  const caps = useRef<(HTMLElement | null)[]>([]);
  const dateBox = useRef<HTMLDivElement>(null);
  const reelHost = useRef<HTMLSpanElement>(null);

  // Dates, months and the focus ring's sequence: a month name, then that month's days.
  const data = useMemo(() => {
    const dates = items.map((i) => toDate(i.date));
    const key = (d: Date) => d.getFullYear() * 12 + d.getMonth();
    const monthOf: number[] = [];
    for (let i = 0; i < n; i++)
      monthOf.push(i === 0 ? 0 : monthOf[i - 1] + (key(dates[i]) === key(dates[i - 1]) ? 0 : 1));
    const months = n ? monthOf[n - 1] + 1 : 0;
    const parts = new Intl.DateTimeFormat(locale, { month: "short", day: "numeric" });
    const long = new Intl.DateTimeFormat(locale, {
      month: "long",
      day: "numeric",
      year: "numeric",
    });
    const monthName = new Intl.DateTimeFormat(locale, { month: "short" });
    const labels = dates.map((d) => {
      const p = parts.formatToParts(d);
      const day = p.findIndex((x) => x.type === "day");
      const join = (xs: Intl.DateTimeFormatPart[]) => xs.map((x) => x.value).join("");
      return {
        prefix: join(p.slice(0, day)),
        day: p[day]?.value ?? "",
        suffix: join(p.slice(day + 1)),
      };
    });
    const ring: { item: number; text: string; month: boolean }[] = [];
    dates.forEach((d, i) => {
      if (i === 0 || monthOf[i] !== monthOf[i - 1])
        ring.push({ item: i, text: monthName.format(d).toUpperCase(), month: true });
      ring.push({ item: i, text: String(d.getDate()), month: false });
    });
    const ringOf = ring.map((r, k) => (r.month ? -1 : k)).filter((k) => k >= 0);
    const monthStart = Array.from({ length: months }, (_, m) => monthOf.indexOf(m));
    return { dates, monthOf, months, labels, ring, ringOf, monthStart, long };
  }, [items, n, locale]);

  const props = useRef({ onChange, onPositionChange, inView, sound, holdDelay, items });
  props.current = { onChange, onPositionChange, inView, sound, holdDelay, items };

  const initial = clamp(value ?? defaultValue ?? n - 1, 0, Math.max(0, n - 1));
  const st = useRef({
    width: 0,
    layout: null as Layout | null,
    index: initial,
    hover: { in: false, x: 0, y: 0, amt: 0, snap: 0, index: -1, slot: -1 },
    press: null as null | {
      id: number;
      x: number;
      y: number;
      moved: boolean;
      touch: boolean;
      timer: number;
    },
    marker: {
      pos: initial,
      from: initial,
      to: initial,
      v0: 0,
      t0: 0,
      dur: 0,
      active: false,
      report: false,
      slot: -1,
    },
    focus: { on: false, amt: 0, anchor: 0, anchorRing: 0, ring: -1 },
    key: { on: false, amt: 0 },
    label: { index: -1, x: 0, shown: false },
    reels: null as null | ((text: string, dir: number, still: boolean) => void)[],
    still: false,
    raf: 0,
    last: 0,
  });
  const s = st.current;

  /* ----- drawing ----- */

  const frame = (now: number) => {
    const L = s.layout;
    s.raf = 0;
    if (!L || !n) return;
    const dt = Math.min(64, now - (s.last || now - 16));
    s.last = now;
    let busy = false;
    const m = s.marker;

    // Marker glide: a cubic Hermite curve that keeps the velocity it had when retargeted.
    if (m.active) {
      const t = clamp((now - m.t0) / m.dur, 0, 1);
      const [t2, t3] = [t * t, t * t * t];
      const v = m.v0 * m.dur;
      m.pos = (2 * t3 - 3 * t2 + 1) * m.from + (t3 - 2 * t2 + t) * v + (3 * t2 - 2 * t3) * m.to;
      if (t >= 1) {
        m.active = false;
        m.pos = m.to;
      } else busy = true;
      if (m.report) props.current.onPositionChange?.(m.pos);
    }
    const markerIndex = clamp(Math.round(m.pos), 0, n - 1);
    const markerX = lerp(
      L.itemX[Math.floor(clamp(m.pos, 0, n - 1))],
      L.itemX[Math.ceil(clamp(m.pos, 0, n - 1))],
      m.pos - Math.floor(m.pos),
    );
    // A ratchet click as the marker reaches each new mark on a move it started.
    const slot = L.itemSlot[markerIndex];
    if (slot !== m.slot) {
      if (m.slot >= 0 && m.report && props.current.sound && !s.hover.in)
        audio.play("travel", Math.abs(slot - m.slot) > 1 ? 0.8 : 1, true);
      m.slot = slot;
    }

    const h = s.hover;
    const pressing = Boolean(s.press);
    const target = h.in || pressing ? 1 : 0;
    h.amt = approach(h.amt, target, target ? 60 : 120, dt);
    s.key.amt = approach(s.key.amt, s.key.on ? 1 : 0, 90, dt);
    s.focus.amt = approach(s.focus.amt, s.focus.on ? 1 : 0, s.focus.on ? 110 : 160, dt);
    const amt = Math.max(h.amt, s.key.amt);
    const fa = s.focus.amt;
    if (
      Math.abs(h.amt - target) > 0.002 ||
      Math.abs(s.key.amt - (s.key.on ? 1 : 0)) > 0.002 ||
      Math.abs(fa - (s.focus.on ? 1 : 0)) > 0.002
    )
      busy = true;

    // The pointer snaps to marks: it rests on one for the first and last 30% of a gap.
    let centre = markerX;
    if (h.in || pressing) {
      const f = (h.x - L.start) / L.gap;
      const base = Math.floor(f);
      const frac = clamp((f - base - 0.3) / 0.4, 0, 1);
      const snapped = L.start + (base + smoother(frac)) * L.gap;
      h.snap = h.amt < 0.05 ? snapped : approach(h.snap, snapped, 35, dt);
      if (Math.abs(h.snap - snapped) > 0.05) busy = true;
      centre = h.snap;
    } else if (s.key.on) centre = markerX;
    else centre = h.snap;

    // In view: darker ticks, the way a scrollbar shows its thumb.
    const [a, b] = props.current.inView ?? [m.pos, m.pos];
    const coverage = (i: number) =>
      clamp(Math.min(b + 0.5, i + 0.5) - Math.max(a - 0.5, i - 0.5), 0, 1);

    // The focus ring hides the ticks it covers.
    const ringCur = s.focus.ring;
    const ringX = (k: number) => s.focus.anchor + (k - s.focus.anchorRing) * PITCH;
    const ringSpan =
      ringCur >= 0 ? [ringX(ringCur) - 4.6 * PITCH, ringX(ringCur) + 4.6 * PITCH] : [0, 0];
    const hidden = (x: number) =>
      fa > 0.001 && x > ringSpan[0] && x < ringSpan[1] ? (1 - fa) ** 1.5 : 1;

    L.slotX.forEach((x, j) => {
      const el = ticks.current[j];
      if (!el) return;
      const r = Math.abs(x - centre) / L.gap;
      const c = Math.max(0, ...L.slotItems[j].map(coverage));
      const height = REST + amt * (1.5 + 4.5 * gauss(r) + 18 * under(r));
      const width = TICK + amt * under(r);
      const opacity = clamp(
        (0.14 + 0.86 * c + amt * (0.12 + 0.3 * gauss(r) + 0.5 * under(r))) * hidden(x),
        0,
        1,
      );
      const hot = Math.round(amt * smooth(clamp((under(r) - 0.12) / 0.24, 0, 1)) * 100);
      const glow = Math.round((amt * 30) / (1 + (r / 1.2) ** 2));
      el.style.transform = `translate3d(${x - width / 2}px, ${MID - height / 2}px, 0)`;
      el.style.width = `${width}px`;
      el.style.height = `${height}px`;
      el.style.opacity = opacity.toFixed(3);
      el.style.background =
        hot || glow
          ? `color-mix(in oklch, var(--tl-hot) ${hot}%, color-mix(in oklch, var(--tl-glow) ${glow}%, currentColor))`
          : "";
    });
    for (let j = L.slotX.length; j < ticks.current.length; j++) {
      const el = ticks.current[j];
      if (el && el.style.opacity !== "0") el.style.opacity = "0";
    }
    L.sepX.forEach((x, j) => {
      const el = seps.current[j];
      if (!el) return;
      const r = Math.abs(x - centre) / L.gap;
      const height = 14 + amt * (2 + 6 * gauss(r));
      el.style.transform = `translate3d(${x - TICK / 2}px, ${MID - height / 2}px, 0)`;
      el.style.height = `${height}px`;
      el.style.opacity = `calc(var(--tl-sep) * ${(hidden(x) * (1 + amt * 0.4 * gauss(r))).toFixed(3)})`;
    });

    // The date above the marks: the hovered item, or the selection when driven by keys.
    const showIndex = h.in || pressing ? (h.index >= 0 ? h.index : markerIndex) : markerIndex;
    const labelOpacity = Math.max(h.amt, s.key.amt) * (1 - fa);
    if (dateBox.current && s.reels) {
      if (showIndex !== s.label.index) {
        const dir = s.label.index < 0 ? 0 : Math.sign(showIndex - s.label.index);
        const lb = data.labels[showIndex];
        const monthChanged =
          s.label.index >= 0 && data.monthOf[showIndex] !== data.monthOf[s.label.index];
        s.reels[0](lb.prefix, monthChanged ? dir : 0, s.still);
        s.reels[1](lb.day.length > 1 ? lb.day.slice(0, -1) : "", dir, s.still);
        s.reels[2](lb.day.slice(-1), dir, s.still);
        s.reels[3](lb.suffix, monthChanged ? dir : 0, s.still);
        if (s.label.index < 0) s.label.x = L.itemX[showIndex];
        s.label.index = showIndex;
      }
      const tx = clamp(L.itemX[showIndex], 36, s.width - 36);
      s.label.x = labelOpacity < 0.02 ? tx : approach(s.label.x, tx, 70, dt);
      if (Math.abs(s.label.x - tx) > 0.1) busy = true;
      dateBox.current.style.transform = `translate3d(${s.label.x}px, 36px, 0) translate(-50%, -100%)`;
      dateBox.current.style.opacity = labelOpacity.toFixed(3);
    }

    // The focus ring: day numbers around the hold point, the current one lit between two caps.
    // Labels off the ring leave the layout, so they never widen the page they sit in.
    data.ring.forEach((entry, k) => {
      const el = fine.current[k];
      if (!el) return;
      const d = Math.abs(k - ringCur);
      const x = ringX(k);
      if (fa < 0.002 || ringCur < 0 || d > 4 || x < 0 || x > s.width) {
        if (el.style.display !== "none") el.style.display = "none";
        return;
      }
      const edge = clamp(Math.min(x, s.width - x) / 24, 0, 1);
      el.style.display = "";
      el.style.opacity = (FINE_OPACITY[d] * fa * edge).toFixed(3);
      el.style.transform = `translate3d(${x}px, ${MID}px, 0) translate(-50%, -50%) scale(${FINE_SCALE[d] * lerp(0.92, 1, fa)})`;
      el.style.color = d === 0 && !entry.month ? "var(--tl-hot)" : "";
    });
    caps.current.forEach((el, i) => {
      if (!el) return;
      const x = ringCur >= 0 ? ringX(ringCur) : 0;
      el.style.opacity = (fa * (ringCur >= 0 ? 1 : 0)).toFixed(3);
      el.style.transform = `translate3d(${x - 1.5}px, ${MID + (i ? 15 : -23) * lerp(0.6, 1, fa)}px, 0)`;
    });

    if (busy) kick();
  };

  const kick = () => {
    if (!s.raf && typeof window !== "undefined") s.raf = requestAnimationFrame(frame);
  };

  /** Moves the marker; `report` is set when the scrubber started the move, so the list follows. */
  const glide = (to: number, mode: "jump" | "scrub" | "step", report: boolean) => {
    const L = s.layout;
    const m = s.marker;
    const now = performance.now();
    let v0 = 0;
    if (m.active) {
      const t = clamp((now - m.t0) / m.dur, 0, 1);
      if (t < 1) {
        const [t2] = [t * t];
        v0 =
          ((6 * t2 - 6 * t) * m.from +
            (3 * t2 - 4 * t + 1) * m.v0 * m.dur +
            (6 * t - 6 * t2) * m.to) /
          m.dur;
      }
    }
    const distance = L ? Math.abs((L.itemX[to] ?? 0) - (L.itemX[Math.round(m.pos)] ?? 0)) : 0;
    const dur =
      mode === "scrub" ? 280 : mode === "step" ? 380 : clamp(460 + distance * 0.08, 520, 950);
    Object.assign(m, { from: m.pos, to, v0, t0: now, dur, active: true, report });
    if (s.still) {
      m.pos = to;
      m.active = false;
      if (report) props.current.onPositionChange?.(to);
    }
    kick();
  };

  const valueText = (i: number) => {
    const item = props.current.items[i];
    return item
      ? `${data.long.format(toDate(item.date))}${item.label ? `, ${item.label}` : ""}`
      : "";
  };
  const announce = (i: number) => {
    root.current?.setAttribute("aria-valuenow", String(i + 1));
    root.current?.setAttribute("aria-valuetext", valueText(i));
  };

  const select = (index: number, mode: "jump" | "scrub" | "step") => {
    const i = clamp(index, 0, n - 1);
    if (i === s.index && !s.marker.active && Math.round(s.marker.pos) === i) return;
    s.index = i;
    announce(i);
    glide(i, mode, true);
    props.current.onChange?.(i);
  };

  // A value set from outside moves the marker quietly; the list that set it is already there.
  // biome-ignore lint/correctness/useExhaustiveDependencies: the scrubber keeps its state in a ref; this runs when the inputs listed change.
  useEffect(() => {
    if (value === undefined || !n) return;
    const v = clamp(value, 0, n - 1);
    if (v === s.index) return;
    s.index = v;
    announce(v);
    glide(v, "jump", false);
  }, [value, n]);

  useEffect(() => {
    if (sound) audio.arm();
  }, [sound]);

  // Layout follows the bar's width.
  // biome-ignore lint/correctness/useExhaustiveDependencies: the scrubber keeps its state in a ref; this runs when the inputs listed change.
  useEffect(() => {
    const el = root.current;
    if (!el) return;
    s.still = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false;
    const place = () => {
      s.width = el.clientWidth;
      s.layout = measure(s.width, data.monthOf, data.months);
      kick();
    };
    place();
    const ro = typeof ResizeObserver === "undefined" ? null : new ResizeObserver(place);
    ro?.observe(el);
    return () => {
      ro?.disconnect();
      cancelAnimationFrame(s.raf);
      s.raf = 0;
    };
  }, [data]);

  // biome-ignore lint/correctness/useExhaustiveDependencies: the scrubber keeps its state in a ref; this runs when the inputs listed change.
  useEffect(() => {
    const host = reelHost.current;
    if (!host) return;
    host.replaceChildren();
    s.reels = [createReel(host), createReel(host), createReel(host), createReel(host)];
    s.label.index = -1;
    kick();
  }, [data]);

  // The in-view range is read on the next frame.
  // biome-ignore lint/correctness/useExhaustiveDependencies: the scrubber keeps its state in a ref; this runs when the inputs listed change.
  useEffect(() => kick(), [inView?.[0], inView?.[1]]);

  /* ----- input ----- */

  const nearest = (x: number) => {
    const L = s.layout;
    if (!L) return 0;
    let best = 0;
    for (let i = 1; i < n; i++)
      if (Math.abs(L.itemX[i] - x) < Math.abs(L.itemX[best] - x)) best = i;
    return best;
  };
  const local = (e: PointerEvent) => {
    const r = root.current!.getBoundingClientRect();
    return { x: e.clientX - r.left, y: e.clientY - r.top };
  };
  const nearestRing = (x: number) => {
    let best = -1;
    data.ringOf.forEach((k) => {
      const dx = Math.abs(s.focus.anchor + (k - s.focus.anchorRing) * PITCH - x);
      if (best < 0 || dx < Math.abs(s.focus.anchor + (best - s.focus.anchorRing) * PITCH - x))
        best = k;
    });
    return best;
  };

  const onPointerMove = (e: PointerEvent) => {
    if (!s.layout) return;
    const p = local(e);
    const h = s.hover;
    h.x = p.x;
    h.y = p.y;
    s.key.on = false;
    // Hover starts near the marks and lasts until the pointer leaves the bar.
    if (!h.in && (e.pointerType === "touch" || Math.abs(p.y - MID) <= 28)) {
      h.in = true;
      root.current?.classList.add("is-held");
      if (props.current.sound) audio.play("line");
    }
    const press = s.press;
    if (s.focus.on) {
      const k = nearestRing(p.x);
      if (k >= 0 && k !== s.focus.ring) {
        s.focus.ring = k;
        if (props.current.sound) audio.play("fine");
        select(data.ring[k].item, "scrub");
      }
    } else if (h.in) {
      h.index = nearest(p.x);
      const slot = s.layout.itemSlot[h.index];
      if (h.slot >= 0 && slot !== h.slot && props.current.sound) {
        const prev = s.layout.slotItems[h.slot][0];
        audio.play(
          data.monthOf[prev] === data.monthOf[h.index] ? "line" : "month",
          Math.abs(slot - h.slot) > 1 ? 0.75 : 1,
        );
      }
      h.slot = slot;
      if (press && !press.moved && Math.abs(p.x - press.x) > 3) {
        press.moved = true;
        window.clearTimeout(press.timer);
      }
      if (press?.moved) select(h.index, "scrub");
    }
    kick();
  };

  const onPointerDown = (e: PointerEvent) => {
    if (e.button !== 0 || !n) return;
    if (props.current.sound) audio.unlock();
    onPointerMove(e);
    if (!s.hover.in) return;
    root.current?.setPointerCapture(e.pointerId);
    const p = local(e);
    const touch = e.pointerType === "touch";
    const press = { id: e.pointerId, x: p.x, y: p.y, moved: false, touch, timer: 0 };
    // Holding still opens the focus ring around the press.
    press.timer = window.setTimeout(
      () => {
        if (s.press !== press || press.moved) return;
        const item = nearest(press.x);
        const k = data.ring.findIndex((r) => !r.month && r.item === item);
        Object.assign(s.focus, {
          on: true,
          anchor: clamp(press.x, EDGE, s.width - EDGE),
          anchorRing: k,
          ring: k,
        });
        if (props.current.sound) audio.play("line", 1.1);
        select(item, "scrub");
        kick();
      },
      touch ? Math.max(props.current.holdDelay, 650) : props.current.holdDelay,
    );
    s.press = press;
    kick();
  };

  const release = (e: PointerEvent) => {
    const press = s.press;
    if (!press || press.id !== e.pointerId) return;
    window.clearTimeout(press.timer);
    s.press = null;
    if (s.focus.on) {
      s.focus.on = false;
      if (props.current.sound) audio.play("close");
    } else if (!press.moved && e.type === "pointerup") select(nearest(local(e).x), "jump");
    if (press.touch) leave();
    kick();
  };

  const leave = () => {
    if (s.press) return;
    s.hover.in = false;
    s.hover.index = -1;
    s.hover.slot = -1;
    root.current?.classList.remove("is-held");
    kick();
  };

  const onKeyDown = (e: KeyboardEvent) => {
    const { monthOf, monthStart } = data;
    const i = s.index;
    const steps: Record<string, number | undefined> = {
      ArrowLeft: i - 1,
      ArrowDown: i - 1,
      ArrowRight: i + 1,
      ArrowUp: i + 1,
      PageUp: monthStart[monthOf[i] + 1] ?? n - 1,
      PageDown:
        monthStart[monthOf[i]] === i ? (monthStart[monthOf[i] - 1] ?? 0) : monthStart[monthOf[i]],
      Home: 0,
      End: n - 1,
    };
    const to = steps[e.key];
    if (to === undefined) return;
    e.preventDefault();
    if (props.current.sound) audio.unlock();
    s.key.on = true;
    select(to, Math.abs(to - i) > 1 ? "jump" : "step");
  };

  const selected = clamp(value ?? s.index, 0, Math.max(0, n - 1));

  // The marks render once per item set; every frame after that only restyles them.
  const marks = useMemo(
    () => (
      <>
        {Array.from({ length: n }, (_, j) => (
          <i
            key={`t${j}`}
            ref={(el) => {
              ticks.current[j] = el;
            }}
            aria-hidden="true"
            className="pointer-events-none absolute top-0 left-0 rounded-full bg-current"
            style={{ width: TICK, height: REST, opacity: 0 } as CSSProperties}
          />
        ))}
        {Array.from({ length: Math.max(0, data.months - 1) }, (_, j) => (
          <i
            key={`s${j}`}
            ref={(el) => {
              seps.current[j] = el;
            }}
            aria-hidden="true"
            className="pointer-events-none absolute top-0 left-0 h-3.5 rounded-full bg-current"
            style={{ width: TICK, opacity: 0 }}
          />
        ))}
        {data.ring.map((r, k) => (
          <span
            key={`f${k}`}
            ref={(el) => {
              fine.current[k] = el;
            }}
            aria-hidden="true"
            className={cx(
              "pointer-events-none absolute top-0 left-0 text-[1.0625rem] leading-none font-semibold whitespace-nowrap tabular-nums",
              r.month && "pl-[0.04em] tracking-[0.04em] text-text-secondary",
            )}
            style={{ display: "none" }}
          >
            {r.text}
          </span>
        ))}
        {[0, 1].map((i) => (
          <i
            key={`c${i}`}
            ref={(el) => {
              caps.current[i] = el;
            }}
            aria-hidden="true"
            className="pointer-events-none absolute top-0 left-0 h-2 w-[3px] rounded-full bg-(--tl-hot)"
            style={{ opacity: 0 }}
          />
        ))}
      </>
    ),
    [data, n],
  );

  return (
    <div
      ref={root}
      role="slider"
      tabIndex={0}
      aria-label={ariaLabel}
      aria-valuemin={1}
      aria-valuemax={Math.max(1, n)}
      aria-valuenow={selected + 1}
      aria-valuetext={n ? valueText(selected) : undefined}
      className={cx(
        "relative h-[6.5rem] w-full touch-none text-text-primary outline-none select-none [-webkit-tap-highlight-color:transparent]",
        "[--tl-glow:var(--tl-hot)] [--tl-hot:#ff9500] [--tl-sep:0.28] dark:[--tl-hot:#ff9f0a] dark:[--tl-sep:0.42]",
        "[&.is-held]:cursor-none",
        className,
      )}
      onPointerEnter={onPointerMove}
      onPointerMove={onPointerMove}
      onPointerDown={onPointerDown}
      onPointerUp={release}
      onPointerCancel={release}
      onPointerLeave={leave}
      onLostPointerCapture={release}
      onKeyDown={onKeyDown}
      onFocus={(e) => {
        if (e.currentTarget.matches(":focus-visible")) {
          s.key.on = true;
          kick();
        }
      }}
      onBlur={() => {
        s.key.on = false;
        kick();
      }}
    >
      {marks}
      <div
        ref={dateBox}
        aria-hidden="true"
        className="pointer-events-none absolute top-0 left-0 text-xl leading-[1.3] font-medium whitespace-pre tabular-nums"
        style={{ opacity: 0 }}
      >
        <span ref={reelHost} className="inline-block" />
      </div>
    </div>
  );
}
